window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0ee07593e9236b32"]={"versions": [{"id": "FIG-0ee07593e9236b32", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>CoreTopology::PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> und Kardinalität <code>2</code> auf <code>PortInterface::DataElementPrototype</code>.\n</li></ul>\n</li><li><code>PortInterface::DataElementPrototype</code> (Stereotyp «atpPrototype», spezialisiert <code>DataPrototype</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ isQueued: Boolean</code>.\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> und Kardinalität <code>2</code> auf <code>PortInterface::OperationPrototype</code>.\n</li></ul>\n</li><li><code>PortInterface::OperationPrototype</code> (Stereotyp «atpStructureElement», spezialisiert <code>Identifiable</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf transitiv durchqueren muss. Die Kardinalität <code>2</code> an den Instanzreferenzen spezifiziert paarweise Referenzen (Sender- und Empfänger-Endpunkte der Software-Komponenten-Interaktion).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Pfadrestriktionen für Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> genau zwei Datenprototypen (<code>+dataElement 2</code>).\n</li><li>Pfadrestriktionen für Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> genau zwei Operationsprototypen (<code>+operation 2</code>) und erfordern die Angabe einer Kommunikationsrichtung (<code>direction</code>).\n</li><li>Die physikalische Route muss als geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) angegeben werden.\n</li><li>Signal-Elemente unterstützen gepufferte bzw. ungepufferte Übertragung über das Attribut <code>isQueued</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4e16b376a465c6e0", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>CoreTopology::PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> und Kardinalität <code>2</code> auf <code>PortInterface::DataElementPrototype</code>.\n</li></ul>\n</li><li><code>PortInterface::DataElementPrototype</code> (Stereotyp «atpPrototype», spezialisiert <code>DataPrototype</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ isQueued: Boolean</code>.\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> und Kardinalität <code>2</code> auf <code>PortInterface::OperationPrototype</code>.\n</li></ul>\n</li><li><code>PortInterface::OperationPrototype</code> (Stereotyp «atpStructureElement», spezialisiert <code>Identifiable</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf transitiv durchqueren muss. Die Kardinalität <code>2</code> an den Instanzreferenzen spezifiziert paarweise Referenzen (Sender- und Empfänger-Endpunkte der Software-Komponenten-Interaktion).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Pfadrestriktionen für Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> genau zwei Datenprototypen (<code>+dataElement 2</code>).\n</li><li>Pfadrestriktionen für Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> genau zwei Operationsprototypen (<code>+operation 2</code>) und erfordern die Angabe einer Kommunikationsrichtung (<code>direction</code>).\n</li><li>Die physikalische Route muss als geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) angegeben werden.\n</li><li>Signal-Elemente unterstützen gepufferte bzw. ungepufferte Übertragung über das Attribut <code>isQueued</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d74d732c6aa9560d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>CoreTopology::PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> und Kardinalität <code>2</code> auf <code>PortInterface::DataElementPrototype</code>.\n</li></ul>\n</li><li><code>PortInterface::DataElementPrototype</code> (Stereotyp «atpPrototype», spezialisiert <code>DataPrototype</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ isQueued: Boolean</code>.\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> und Kardinalität <code>2</code> auf <code>PortInterface::OperationPrototype</code>.\n</li></ul>\n</li><li><code>PortInterface::OperationPrototype</code> (Stereotyp «atpStructureElement», spezialisiert <code>Identifiable</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf transitiv durchqueren muss. Die Kardinalität <code>2</code> an den Instanzreferenzen spezifiziert paarweise Referenzen (Sender- und Empfänger-Endpunkte der Software-Komponenten-Interaktion).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Pfadrestriktionen für Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> genau zwei Datenprototypen (<code>+dataElement 2</code>).\n</li><li>Pfadrestriktionen für Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> genau zwei Operationsprototypen (<code>+operation 2</code>) und erfordern die Angabe einer Kommunikationsrichtung (<code>direction</code>).\n</li><li>Die physikalische Route muss als geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) angegeben werden.\n</li><li>Signal-Elemente unterstützen gepufferte bzw. ungepufferte Übertragung über das Attribut <code>isQueued</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d9c76940df1b0f75", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> (implizite Kardinalität 1) auf <code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> (implizite Kardinalität 1) auf <code>ClientServerOperation</code> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf durchqueren muss. Die Instanzreferenzen verknüpfen die Pfaddefinition mit den jeweiligen Software-Komponenten-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> ein <code>VariableDataPrototype</code> über die Instanzreferenz <code>+dataElement</code>. Das Attribut <code>isQueued</code> ist nicht mehr Bestandteil der Datenprototyp-Definition an dieser Stelle.\n</li><li>Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> eine <code>ClientServerOperation</code> über die Instanzreferenz <code>+operation</code> und erfordern die Angabe der Übertragungsrichtung (<code>direction</code>).\n</li><li>Die physikalische Kanalroute wird über eine geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) festgelegt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d0500042b90627c3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> (implizite Kardinalität 1) auf <code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> (implizite Kardinalität 1) auf <code>ClientServerOperation</code> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf durchqueren muss. Die Instanzreferenzen verknüpfen die Pfaddefinition mit den jeweiligen Software-Komponenten-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> ein <code>VariableDataPrototype</code> über die Instanzreferenz <code>+dataElement</code>. Das Attribut <code>isQueued</code> ist nicht mehr Bestandteil der Datenprototyp-Definition an dieser Stelle.\n</li><li>Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> eine <code>ClientServerOperation</code> über die Instanzreferenz <code>+operation</code> und erfordern die Angabe der Übertragungsrichtung (<code>direction</code>).\n</li><li>Die physikalische Kanalroute wird über eine geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) festgelegt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a2c12554cd42f1c8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> (implizite Kardinalität 1) auf <code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> (implizite Kardinalität 1) auf <code>ClientServerOperation</code> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf durchqueren muss. Die Instanzreferenzen verknüpfen die Pfaddefinition mit den jeweiligen Software-Komponenten-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> ein <code>VariableDataPrototype</code> über die Instanzreferenz <code>+dataElement</code>. Das Attribut <code>isQueued</code> ist nicht mehr Bestandteil der Datenprototyp-Definition an dieser Stelle.\n</li><li>Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> eine <code>ClientServerOperation</code> über die Instanzreferenz <code>+operation</code> und erfordern die Angabe der Übertragungsrichtung (<code>direction</code>).\n</li><li>Die physikalische Kanalroute wird über eine geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) festgelegt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-23bddc3cdefe69e4", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> und expliziter Kardinalität <code>1</code> (<code>+dataElement 1</code>) auf <code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction :SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> und expliziter Kardinalität <code>1</code> (<code>+operation 1</code>) auf <code>ClientServerOperation</code> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf durchqueren muss. Die Instanzreferenzen verknüpfen die Pfaddefinition mit den jeweiligen Software-Komponenten-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> ein <code>VariableDataPrototype</code> über die Instanzreferenz <code>+dataElement</code>. Das Attribut <code>isQueued</code> ist nicht mehr Bestandteil der Datenprototyp-Definition an dieser Stelle.\n</li><li>Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> eine <code>ClientServerOperation</code> über die Instanzreferenz <code>+operation</code> und erfordern die Angabe der Übertragungsrichtung (<code>direction</code>).\n</li><li>Die physikalische Kanalroute wird über eine geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) festgelegt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7a9c96fe187a8a36", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation topologischer Signalpfad-Restriktionen (<code>SignalPathConstraint</code>) im Kontext der AUTOSAR-Systembeschreibung (System Template). Das Diagramm modelliert, über welche geordnete Sequenz von physikalischen Kommunikationskanälen Signale und Operationsaufrufe zwischen Software-Komponenten übertragen werden dürfen (<code>PermissibleSignalPath</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PermissibleSignalPath</code> (spezialisiert <code>SignalPathConstraint</code>): Zentrales Element zur Definition zulässiger Pfade in der Bus-Topologie.\n<ul class=\"fig-list\"><li>Komposition <code>+signal</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcSignal</code>.\n</li><li>Komposition <code>+operation</code> mit Multiplizität <code>*</code> zu <code>SwcToSwcOperationArguments</code>.\n</li><li>Unidirektionale gerichtete Assoziation <code>+physicalChannel</code> mit Kardinalität <code>1..* {ordered}</code> zu <code>PhysicalChannel</code> (spezialisiert <code>Identifiable</code>).\n</li></ul>\n</li><li><code>PhysicalChannel</code>:\n<ul class=\"fig-list\"><li>Selbstassoziation <code>+managedPhysicalChannel</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>SwcToSwcSignal</code>:\n<ul class=\"fig-list\"><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+dataElement</code> und expliziter Kardinalität <code>1</code> (<code>+dataElement 1</code>) auf <code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).\n</li></ul>\n</li><li><code>SwcToSwcOperationArguments</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ direction: SwcToSwcOperationArgumentsDirectionEnum</code>.\n</li><li>Instanzreferenz (<code>«instanceRef»</code>) mit Rollenbezeichnung <code>+operation</code> und expliziter Kardinalität <code>1</code> (<code>+operation 1</code>) auf <code>ClientServerOperation</code> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Ablaufsemantik. Die Kompositionsbeziehungen drücken aus, dass ein <code>PermissibleSignalPath</code> Mengen von <code>SwcToSwcSignal</code>- und <code>SwcToSwcOperationArguments</code>-Definitionen bündelt. Die Eigenschaft <code>{ordered}</code> der Assoziation zu <code>PhysicalChannel</code> legt eine geordnete Abfolge von Kanälen fest, die ein Signal bzw. ein Operationsaufruf durchqueren muss. Die Instanzreferenzen verknüpfen die Pfaddefinition mit den jeweiligen Software-Komponenten-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von System- und Topologiebeschreibungen müssen beachten:</p>\n<ul class=\"fig-list\"><li>Sender-Receiver-Signale referenzieren über <code>SwcToSwcSignal</code> ein <code>VariableDataPrototype</code> über die Instanzreferenz <code>+dataElement</code>. Das Attribut <code>isQueued</code> ist nicht mehr Bestandteil der Datenprototyp-Definition an dieser Stelle.\n</li><li>Client-Server-Operationen referenzieren über <code>SwcToSwcOperationArguments</code> eine <code>ClientServerOperation</code> über die Instanzreferenz <code>+operation</code> und erfordern die Angabe der Übertragungsrichtung (<code>direction</code>).\n</li><li>Die physikalische Kanalroute wird über eine geordnete Liste aus mindestens einem <code>PhysicalChannel</code> (<code>1..* {ordered}</code>) festgelegt.\n</li><li>Ein <code>PhysicalChannel</code> kann optional über <code>+managedPhysicalChannel</code> (<code>0..*</code>) untergeordnete bzw. verwaltete Kanäle referenzieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0ee07593e9236b32", "to": "FIG-4e16b376a465c6e0", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4e16b376a465c6e0", "to": "FIG-d74d732c6aa9560d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Attribut <code>SwcToSwcOperationArguments.direction</code>: Leerzeichenverschiebung vor dem Doppelpunkt (<code>+ direction :SwcToSwcOperationArgumentsDirectionEnum</code>).\n</li><li>Attribut <code>PortInterface::DataElementPrototype.isQueued</code>: Leerzeichenverschiebung vor dem Doppelpunkt (<code>+ isQueued :Boolean</code>).\n</li><li>Minimaler horizontaler Versatz der Klassenboxen im rechten Diagrammbereich.\n</li></ul>"}, {"from": "FIG-d74d732c6aa9560d", "to": "FIG-d9c76940df1b0f75", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ziel der Instanzreferenz <code>+dataElement</code> von <code>«atpPrototype» PortInterface::DataElementPrototype</code> (Spezialisierung von <code>DataPrototype</code>) mit Attribut <code>+ isQueued: Boolean</code> auf <code>VariableDataPrototype</code> (Spezialisierung von <code>AutosarDataPrototype</code>) geändert.\n</li><li>Ziel der Instanzreferenz <code>+operation</code> von <code>PortInterface::OperationPrototype</code> (Stereotyp «atpStructureElement», Basisklasse <code>Identifiable</code>) auf <code>ClientServerOperation</code> (Spezialisierungen <code>AtpStructureElement</code>, <code>Identifiable</code>) geändert.\n</li><li>Kardinalität der Instanzreferenz <code>+dataElement</code> von <code>2</code> auf <code>1</code> (implizit) reduziert.\n</li><li>Kardinalität der Instanzreferenz <code>+operation</code> von <code>2</code> auf <code>1</code> (implizit) reduziert.\n</li><li>Zieltyp der Assoziation <code>+physicalChannel</code> von <code>CoreTopology::PhysicalChannel</code> auf <code>PhysicalChannel</code> umbenannt/vereinfacht.\n</li><li>Layout des Klassendiagramms neu gerendert.\n</li></ul>"}, {"from": "FIG-d9c76940df1b0f75", "to": "FIG-d0500042b90627c3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d0500042b90627c3", "to": "FIG-a2c12554cd42f1c8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a2c12554cd42f1c8", "to": "FIG-23bddc3cdefe69e4", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Zielrolle <code>+dataElement</code>: Kardinalität explizit mit <code>1</code> annotiert (<code>+dataElement 1</code>).\n</li><li>Zielrolle <code>+operation</code>: Kardinalität explizit mit <code>1</code> annotiert (<code>+operation 1</code>).\n</li><li>Assoziationsbeschriftungen am Pfeilkopf von <code>+physicalChannel</code> leicht verschoben.\n</li></ul>"}, {"from": "FIG-23bddc3cdefe69e4", "to": "FIG-7a9c96fe187a8a36", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PhysicalChannel</code>: Selbstassoziation <code>+managedPhysicalChannel</code> mit Kardinalität <code>0..*</code> ergänzt.\n</li></ul>"}]};
